/**
 * "Blocked by" links between issues. Every method takes `orgId` first. A blocker is *open* while it is live and
 * its status is neither `done` nor `canceled`; the predicate lives here so the
 * completion gate, the unblock reaction and the cascade all agree on it.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, exists, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { SQL } from "drizzle-orm";

/** What `insertDependency` did; `cycle` means nothing was stored. */
export type InsertDependencyOutcome =
  | { readonly kind: "created"; readonly dependency: IssueDependency }
  | { readonly kind: "exists"; readonly dependency: IssueDependency }
  | { readonly kind: "cycle" };

/** Live and neither `done` nor `canceled`. */
function openPredicate(): readonly SQL[] {
  return compact(
    livePredicate(issues.archivedAt, {}),
    notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
  );
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/**
 * Stores "`issueId` is blocked by `blockerId`" unless the link already exists
 * or would close a cycle. The lookup, the reachability walk and the insert run
 * in one synchronous transaction, so two concurrent calls cannot each pass the
 * cycle check and then both insert.
 */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<InsertDependencyOutcome> {
  return getDb().transaction((tx): InsertDependencyOutcome => {
    const existing = tx
      .select()
      .from(issueDependencies)
      .where(
        and(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          eq(issueDependencies.blockerId, blockerId),
        ),
      )
      .get();
    if (existing) {
      return { kind: "exists", dependency: toIssueDependency(existing) };
    }

    // The new edge closes a cycle iff `issueId` is already reachable from
    // `blockerId` by following "is blocked by" links. Archived issues keep
    // their links, so they are walked like any other.
    const seen = new Set<string>([blockerId]);
    let frontier: string[] = [blockerId];
    while (frontier.length > 0) {
      const rows = tx
        .select({ blockerId: issueDependencies.blockerId })
        .from(issueDependencies)
        .where(
          and(
            orgPredicate(issueDependencies.orgId, orgId),
            inArray(issueDependencies.issueId, frontier),
          ),
        )
        .all();

      const next: string[] = [];
      for (const row of rows) {
        if (row.blockerId === issueId) return { kind: "cycle" };
        if (seen.has(row.blockerId)) continue;
        seen.add(row.blockerId);
        next.push(row.blockerId);
      }
      frontier = next;
    }

    const row = tx
      .insert(issueDependencies)
      .values({
        orgId,
        issueId,
        blockerId,
        createdBy,
        createdAt: toIsoTimestamp(new Date()),
      })
      .returning()
      .get();

    return { kind: "created", dependency: toIssueDependency(row) };
  });
}

/** Resolves `true` when a link was removed, `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ blockerId: issueDependencies.blockerId })
    .all();
  return rows.length > 0;
}

/** Live blockers of an issue (open or closed), by issue number. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          orgPredicate(issues.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all()
    .map((row) => row.issue);

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Ids of the issue's open blockers, by issue number. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        ...openPredicate(),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => row.id as IssueId);
}

/** Every issue (any state) that lists `blockerId` as a blocker. */
export async function listBlockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.issueId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/**
 * Open issues of one project that block at least one issue — the blockers a
 * project archive cascade is about to close.
 */
export async function listOpenBlockerIdsInProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueId[]> {
  const db = getDb();
  const rows = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        ...openPredicate(),
        exists(
          db
            .select({ blockerId: issueDependencies.blockerId })
            .from(issueDependencies)
            .where(
              and(
                orgPredicate(issueDependencies.orgId, orgId),
                eq(issueDependencies.blockerId, issues.id),
              ),
            ),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => row.id as IssueId);
}
EOF

