    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Ids of the issue's open blockers, by issue number. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        ...openPredicate(),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => row.id as IssueId);
}

/** Every issue (any state) that lists `blockerId` as a blocker. */
export async function listBlockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.issueId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/**
 * Open issues of one project that block at least one issue — the blockers a
 * project archive cascade is about to close.
 */
export async function listOpenBlockerIdsInProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueId[]> {
  const db = getDb();
  const rows = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        ...openPredicate(),
        exists(
          db
            .select({ blockerId: issueDependencies.blockerId })
            .from(issueDependencies)
            .where(
              and(
                orgPredicate(issueDependencies.orgId, orgId),
                eq(issueDependencies.blockerId, issues.id),
              ),
            ),
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
  return rows.map((row) => row.id as IssueId);
}
