 * Records "`issueId` is blocked by `blockerId`". Both issues must exist in the
 * org and be live; a link that would block an issue on itself, directly or
 * through a chain of other links, is refused. Adding a link that already
 * exists returns it unchanged.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  const outcome = await dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
  if (outcome.kind === "cycle") {
    throw new Error(
      `Issue ${blocker.id} cannot block issue ${issue.id}: that would create a dependency cycle`,
    );
  }

  return outcome.dependency;
}

