/**
 * Tells an assignee that their issue has just lost its last open blocker.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * For every issue blocked by one of `closedBlockerIds` (blockers that have
 * just gone from open to closed), sends one `issue_unblocked` notification to
 * its assignee — provided the issue is still live and unfinished and no open
 * blocker remains. `notify` applies the usual delivery rules, so the actor is
 * never told about their own action and muted recipients are skipped.
 */
async function notifyUnblocked(
  orgId: OrgId,
  closedBlockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const handled = new Set<IssueId>();

  for (const blockerId of closedBlockerIds) {
    for (const blocked of await dependencyRepo.listBlockedIssues(
      orgId,
      blockerId,
    )) {
      if (handled.has(blocked.id)) continue;
      handled.add(blocked.id);

      if (blocked.archivedAt !== null || isClosedStatus(blocked.status)) continue;
      if (blocked.assigneeId === null) continue;

      const stillBlocked = await dependencyRepo.listOpenBlockerIds(
        orgId,
        blocked.id,
      );
      if (stillBlocked.length > 0) continue;

      await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
        title: "An issue is unblocked",
        body: `Issue ${blocked.title} has no open blockers left`,
        href: `/issues/${blocked.id}`,
        actorId,
      });
    }
  }
}

/**
 * A blocker closes by moving to `done`/`canceled`, by being archived while
 * still open, or by a project archive cascade taking it along. Closed-to-closed
 * changes and reopenings never reach `notifyUnblocked`.
 */
export function registerUnblockListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    // Archiving leaves the status untouched, so the row still says whether the
    // issue was open when it was archived.
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (issue === null || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("project.archived", async (payload) => {
      if (payload.closedBlockerIds === undefined) return;
      await notifyUnblocked(
        payload.orgId,
        payload.closedBlockerIds,
        payload.actorId,
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
