mkdir -p tests/_tmp && cat > tests/_tmp/deps.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { registerEventHandlers } from "@/server/services/event-registry";
import * as deps from "@/server/services/issue-dependency-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as notificationService from "@/server/services/notification-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { NotFoundError } from "@/server/services/_support";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("deps", "growth");
  registerEventHandlers();
});
afterAll(() => cleanup());

async function mk(title: string, assignee: UserId | null = null) {
  return issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title, assigneeId: assignee }));
}
async function notifs(user: UserId) {
  const page = await notificationService.listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: user, unreadOnly: false, kind: ["issue_unblocked"], limit: 50, cursor: null });
  return page.items;
}

describe("deps", () => {
  it("add/list/remove + rules", async () => {
    const a = await mk("aaa"), b = await mk("bbb"), c = await mk("ccc");
    const inp = (i: typeof a, bl: typeof a) => ({ orgId: t.org.id, issueId: i.id, blockerId: bl.id });
    const link = await deps.addBlocker(t.actors.member, inp(a, b));
    expect(link.createdBy).toBe(t.userIds.member);
    const again = await deps.addBlocker(t.actors.admin, inp(a, b));
    expect(again).toEqual(link);
    await expect(deps.addBlocker(t.actors.member, inp(a, a))).rejects.toThrow();
    await expect(deps.addBlocker(t.actors.member, inp(b, a))).rejects.toThrow();
    await deps.addBlocker(t.actors.member, inp(b, c));
    await expect(deps.addBlocker(t.actors.member, inp(c, a))).rejects.toThrow(/cycle/);
    await expect(deps.addBlocker(t.actors.viewer, inp(c, b))).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(deps.addBlocker({ ...t.actors.member, orgId: "x" as never }, inp(c, b))).rejects.toBeInstanceOf(TenantScopeError);
    await expect(deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: "nope" as never })).rejects.toBeInstanceOf(NotFoundError);
    expect((await deps.listBlockers(t.actors.viewer, t.org.id, a.id)).map((i) => i.id)).toEqual([b.id]);
    expect(await deps.removeBlocker(t.actors.member, inp(a, b))).toBe(true);
    expect(await deps.removeBlocker(t.actors.member, inp(a, b))).toBe(false);
    await deps.addBlocker(t.actors.member, inp(a, b));
    await issueService.archiveIssue(t.actors.member, t.org.id, c.id);
    await expect(deps.addBlocker(t.actors.member, inp(a, c))).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await deps.listBlockers(t.actors.viewer, t.org.id, b.id))).toEqual([]);
  });

  it("gate + notifications", async () => {
    const assignee = t.userIds.admin;
    const a = await mk("gated", assignee), x = await mk("x"), y = await mk("y");
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: x.id });
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: y.id });
    const st = (i: typeof a, status: "done" | "canceled" | "todo") => issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: i.id, status });
    const err = await st(a, "done").catch((e) => e);
    expect(err).toBeInstanceOf(deps.IssueBlockedError);
    expect(err.blockerIds).toEqual([x.id, y.id]);
    await expect(issueService.moveIssue(t.actors.member, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 })).rejects.toBeInstanceOf(deps.IssueBlockedError);
    await st(a, "todo");
    await st(x, "done");
    expect(await notifs(assignee)).toHaveLength(0);
    await expect(st(a, "done")).rejects.toMatchObject({ blockerIds: [y.id] });
    await st(y, "canceled");
    let n = await notifs(assignee);
    expect(n).toHaveLength(1);
    expect(n[0]).toMatchObject({ href: `/issues/${a.id}`, actorId: t.userIds.member, kind: "issue_unblocked" });
    await st(y, "done"); // closed->closed
    expect(await notifs(assignee)).toHaveLength(1);
    await st(y, "todo"); await st(y, "done");
    expect(await notifs(assignee)).toHaveLength(2);
    await st(a, "done");
    // blocked done => no notify on new close
    const z = await mk("z");
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: z.id });
    await issueService.archiveIssue(t.actors.member, t.org.id, z.id);
    expect(await notifs(assignee)).toHaveLength(2);
  });

  it("archive notifies; own action suppressed; prefs honoured; cascade", async () => {
    const assignee = t.userIds.viewer;
    const a = await mk("blocked", assignee), x = await mk("xx");
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: x.id });
    await issueService.archiveIssue(t.actors.admin, t.org.id, x.id);
    expect(await notifs(assignee)).toHaveLength(1);

    const own = t.userIds.member;
    const b = await mk("own", own), y = await mk("yy");
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: b.id, blockerId: y.id });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: y.id, status: "done" });
    expect(await notifs(own)).toHaveLength(0);

    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.owner, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false });
    const c = await mk("muted", t.userIds.owner), z = await mk("zz");
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: z.id });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: z.id, status: "canceled" });
    expect(await notifs(t.userIds.owner)).toHaveLength(0);

    // cascade: blocker in another project
    const p2 = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "Other", slug: "other", key: "OTH", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const w = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p2.id, { title: "in other" }));
    const d = await mk("dd", assignee);
    await deps.addBlocker(t.actors.member, { orgId: t.org.id, issueId: d.id, blockerId: w.id });
    const before = (await notifs(assignee)).length;
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p2.id, archiveIssues: true });
    expect(await notifs(assignee)).toHaveLength(before + 1);
  });
});
EOF
